from flask import Flask, request, send_file, abort, jsonify
import os
import logging
import hashlib
import time

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = '/var/app/uploads'
app.config['SECRET_KEY'] = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

logger = logging.getLogger(__name__)

def sanitize_filename(filename):
    """Remove null bytes and normalize slashes."""
    filename = filename.replace('\x00', '')
    # Normalize backslashes to forward slashes for consistency
    filename = filename.replace('\\', '/')
    return filename

def validate_token(token):
    """Validate download token using HMAC-like check."""
    if not token or len(token) < 8:
        return False
    expected_prefix = hashlib.md5(app.config['SECRET_KEY'].encode()).hexdigest()[:8]
    return token.startswith(expected_prefix)

@app.route('/health')
def health():
    return jsonify({"status": "ok", "timestamp": time.time()})

@app.route('/api/v1/documents/<path:filepath>')
def download_document(filepath):
    """Download a document from the uploads directory.

    Requires valid auth token in X-Download-Token header.
    Files are served relative to UPLOAD_FOLDER.
    """
    token = request.headers.get('X-Download-Token', '')
    if not validate_token(token):
        abort(401)

    # Sanitize the input
    clean_path = sanitize_filename(filepath)

    # Log access attempt
    logger.info(f"Document request: {clean_path} from {request.remote_addr}")

    # Build the full path
    full_path = os.path.join(app.config['UPLOAD_FOLDER'], clean_path)

    # Check file exists
    if not os.path.isfile(full_path):
        abort(404)

    # Serve the file
    return send_file(full_path, as_attachment=True)

@app.route('/api/v1/documents', methods=['POST'])
def upload_document():
    """Upload a document to the uploads directory."""
    token = request.headers.get('X-Download-Token', '')
    if not validate_token(token):
        abort(401)

    if 'file' not in request.files:
        abort(400)

    f = request.files['file']
    if f.filename == '':
        abort(400)

    # Save with original filename
    safe_name = os.path.basename(f.filename)
    dest = os.path.join(app.config['UPLOAD_FOLDER'], safe_name)
    f.save(dest)

    return jsonify({"status": "uploaded", "filename": safe_name}), 201

@app.errorhandler(404)
def not_found(e):
    return jsonify({"error": "not found"}), 404

@app.errorhandler(401)
def unauthorized(e):
    return jsonify({"error": "unauthorized"}), 401

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
